def game_score(points: str) -> str:
    # score values in order of points gained
    score_order = [0, 15, 30, 40]
    # mapping from numeric score to string representation
    score_map = {0: "0", 15: "15", 30: "30", 40: "40"}

    a_pts = 0
    b_pts = 0
    a_score = 0
    b_score = 0

    for p in points:
        if p == 'A':
            a_pts += 1
        elif p == 'B':
            b_pts += 1
        else:
            # ignore invalid characters
            continue

        # Determine if someone has won the game
        if a_pts >= 4 or b_pts >= 4:
            # Normal tennis scoring: need 2 points lead after at least 4 points
            if abs(a_pts - b_pts) >= 2:
                return "Game A" if a_pts > b_pts else "Game B"
            # No‑ad rule: at 40‑40 (i.e. both at least 3 points) next point decides
            if a_pts >= 3 and b_pts >= 3 and a_pts == b_pts:
                continue  # still tied, wait for next point
            if a_pts >= 3 and b_pts >= 3 and a_pts != b_pts:
                return "Game A" if a_pts > b_pts else "Game B"

        # Update score strings only up to 40
        if a_pts <= 3:
            a_score = score_order[a_pts]
        else:
            a_score = 40

        if b_pts <= 3:
            b_score = score_order[b_pts]
        else:
            b_score = 40

    # No winner yet – return current score
    return f"{score_map[a_score]}-{score_map[b_score]}"
